type Stats struct {
    mu     sync.Mutex
    counts map[string]int
}

func (s *Stats) Inc(key string) {
    s.mu.Lock()
    defer s.mu.Unlock()
    s.counts[key]++
}

func (s *Stats) Snapshot() map[string]int {
    s.mu.Lock()
    defer s.mu.Unlock()
    return maps.Clone(s.counts)   // отдать копию, а не ссылку на защищаемые данные
}
